import { ExternalLink, RefreshCw, ShieldCheck } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { formatPeso } from '@/lib/payments';

type PaymongoQrPaymentProps = {
  amount: number;
  checkoutUrl?: string | null;
  onRetry?: () => void;
  retrying?: boolean;
  deferred?: boolean;
};

/**
 * Payment QR instructions. The QR itself is generated by PayMongo inside the
 * booking-specific Checkout Session, so a static merchant QR must never be
 * used as an automatic online-payment fallback.
 */
export default function PaymongoQrPayment({ amount, checkoutUrl, onRetry, retrying = false, deferred = false }: PaymongoQrPaymentProps) {
  return (
    <div className="rounded-xl border border-primary/20 bg-primary/5 p-4 space-y-3">
      <div className="flex items-start justify-between gap-3">
        <div>
          <p className="font-semibold text-primary">Pay with QR Ph</p>
          <p className="text-xs text-muted-foreground mt-0.5">
            Scan the live merchant QR with your bank or e-wallet app.
          </p>
        </div>
        <ShieldCheck className="h-5 w-5 shrink-0 text-primary" aria-hidden="true" />
      </div>

      {checkoutUrl ? (
        <div className="space-y-3 rounded-lg border border-primary/20 bg-background/60 p-4 text-center">
          <p className="text-sm font-semibold text-foreground">Secure QRPh checkout ready</p>
          <p className="text-xs text-muted-foreground">PayMongo generated a unique QRPh payment for this booking and exact amount. Open it to scan, then the signed webhook will verify payment automatically.</p>
          <a
            href={checkoutUrl}
            target="_blank"
            rel="noreferrer"
            className="inline-flex w-full items-center justify-center rounded-lg bg-primary px-3 py-2 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90"
          >
            Open secure QRPh checkout <ExternalLink className="ml-1.5 h-4 w-4" aria-hidden="true" />
          </a>
        </div>
      ) : deferred ? (
        <div className="space-y-2 rounded-lg border border-primary/20 bg-background/60 p-4 text-center">
          <p className="text-sm font-semibold text-foreground">Secure QRPh checkout will be generated after submission</p>
          <p className="text-xs text-muted-foreground">After you confirm this reservation, PayMongo will create a unique QRPh payment for the exact amount.</p>
        </div>
      ) : (
        <div className="space-y-3 rounded-lg border border-warning/30 bg-warning/10 p-4 text-center">
          <p className="text-sm font-semibold text-foreground">Secure QRPh checkout is not ready yet</p>
          <p className="text-xs text-muted-foreground">A unique payment QR must be generated before you pay. No static QR or manual payment verification is used for online reservations.</p>
          {onRetry && (
            <Button type="button" variant="outline" className="w-full" onClick={onRetry} disabled={retrying}>
              <RefreshCw className={`mr-1.5 h-4 w-4 ${retrying ? 'animate-spin' : ''}`} aria-hidden="true" />
              {retrying ? 'Generating secure QRPh…' : 'Generate secure QRPh payment'}
            </Button>
          )}
        </div>
      )}

      <div className="space-y-1 text-xs">
        <p>Amount to send: <strong>{formatPeso(amount)}</strong></p>
        <p className="text-muted-foreground">
          {checkoutUrl ? 'Open the secure checkout to scan your generated QRPh code. No receipt upload is required here.' : 'Payment becomes available after PayMongo generates a unique QRPh code for this booking.'}
        </p>
      </div>

      <a
        href="https://www.paymongo.com/"
        target="_blank"
        rel="noreferrer"
        className="inline-flex items-center gap-1 text-xs text-primary underline-offset-2 hover:underline"
      >
        Powered by PayMongo <ExternalLink className="h-3 w-3" aria-hidden="true" />
      </a>
    </div>
  );
}
